// These guards consume unknown IPC values without constructing a second copy of large views.
// Mapped fields require every declared DTO property to have a validator; unknown keys fail.
type Guard<T> = (value: unknown) => value is T;
function isObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const prototype: unknown = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}
const isText = (value: unknown): value is string =>
  typeof value === "string" && value.length <= 1_048_576;
const isBoolean = (value: unknown): value is boolean => typeof value === "boolean";
const isRevision = (value: unknown): value is Revision =>
  typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
const isU32 = (value: unknown): value is number => isRevision(value) && value <= 4_294_967_295;
const isUuid = (value: unknown): value is UuidV7 =>
  typeof value === "string" &&
  /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(value);
const isPackId = (value: unknown): value is PackId =>
  typeof value === "string" &&
  value.length <= 128 &&
  value.includes(".") &&
  value.split(".").every((part) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(part));
const isDigest = (value: unknown): value is string =>
  typeof value === "string" && /^[0-9a-f]{64}$/.test(value);
const isRunDiagnosticCode = (value: unknown): value is string =>
  typeof value === "string" &&
  value.length <= 96 &&
  value.split(".").length >= 2 &&
  value.split(".").every((part) => /^[a-z0-9](?:[a-z0-9_-]*[a-z0-9])?$/.test(part));
const isDomainId = (value: unknown): value is string =>
  typeof value === "string" &&
  value.length <= 160 &&
  value.split(".").length >= 2 &&
  value.split(".").every((part) => /^[a-z0-9](?:[a-z0-9_-]*[a-z0-9])?$/.test(part));
const isValidationIssueId = (value: unknown): value is string =>
  isDomainId(value) ||
  (typeof value === "string" && /^validation\.issue\.[0-9a-f]{64}$/.test(value));

function literal<const T extends string | number | boolean>(expected: T): Guard<T> {
  return (value: unknown): value is T => value === expected;
}
function choices<const T extends string>(...values: readonly T[]): Guard<T> {
  return (value: unknown): value is T => values.some((candidate) => candidate === value);
}
function nullable<T>(guard: Guard<T>): Guard<T | null> {
  return (value: unknown): value is T | null => value === null || guard(value);
}
function optional<T>(guard: Guard<T>): Guard<T | undefined> {
  return (value: unknown): value is T | undefined => value === undefined || guard(value);
}
function arrayOf<T>(guard: Guard<T>, maximum = 1_000_000): Guard<readonly T[]> {
  return (value: unknown): value is readonly T[] =>
    Array.isArray(value) && value.length <= maximum && value.every(guard);
}
function union<T>(...guards: readonly Guard<T>[]): Guard<T> {
  return (value: unknown): value is T => guards.some((guard) => guard(value));
}
function recordOf<T>(
  guard: Guard<T>,
  keyGuard: Guard<string> = isText,
  maximum = 1_000_000,
): Guard<Readonly<Record<string, T>>> {
  return (value: unknown): value is Readonly<Record<string, T>> => {
    if (!isObject(value)) return false;
    const keys = Object.keys(value);
    return keys.length <= maximum && keys.every((key) => keyGuard(key) && guard(value[key]));
  };
}
function shape<T extends object>(fields: { readonly [K in keyof T]-?: Guard<T[K]> }): Guard<T> {
  return (value: unknown): value is T => {
    if (!isObject(value) || Object.keys(value).some((key) => !Object.hasOwn(fields, key)))
      return false;
    for (const key in fields) {
      if (!fields[key](Object.hasOwn(value, key) ? value[key] : undefined)) return false;
    }
    return true;
  };
}

function isCalendarDate(year: number, month: number, day: number): boolean {
  // Jiff permits year zero, but its signed negative-zero spelling is invalid.
  if (Object.is(year, -0) || year < -9999 || year > 9999 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const maximum =
    month === 2
      ? leap
        ? 29
        : 28
      : month === 4 || month === 6 || month === 9 || month === 11
        ? 30
        : 31;
  return day >= 1 && day <= maximum;
}

// Check calendar fields explicitly: Date.parse normalizes invalid dates and loses nanoseconds.
function isTimestamp(value: unknown): value is string {
  if (typeof value !== "string" || value.length > 40) return false;
  const match =
    /^([0-9]{4}|[+-][0-9]{6})-([0-9]{2})-([0-9]{2})[Tt]([0-9]{2}):([0-9]{2}):([0-9]{2})(?:\.[0-9]{1,9})?(?:[Zz]|([+-])([0-9]{2}):([0-9]{2}))$/.exec(
      value,
    );
  if (match === null) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const hour = Number(match[4]);
  const minute = Number(match[5]);
  const second = Number(match[6]);
  const offsetHours = Number(match[8] ?? "0");
  const offsetMinutes = Number(match[9] ?? "0");
  if (
    !isCalendarDate(year, month, day) ||
    hour > 23 ||
    minute > 59 ||
    second > 59 ||
    offsetHours > 23 ||
    offsetMinutes > 59
  )
    return false;
  if (year !== -9999 && year !== 9999) return true;
  // Only extreme civil years can cross Jiff Timestamp::MIN/MAX after offset conversion.
  // Validated fields avoid Date normalization; integer seconds preserve all nanoseconds:
  // MIN has fraction zero and MAX has fraction 999999999.
  const offset = (offsetHours * 3600 + offsetMinutes * 60) * (match[7] === "-" ? -1 : 1);
  const instant = Date.UTC(year, month - 1, day, hour, minute, second) / 1000 - offset;
  return instant >= -377705023201 && instant <= 253402207200;
}

// Count compact JSON bytes in-place, including escaping, without stringify/UTF-8 buffer copies.
function boundedJson(value: unknown, maximum: number): value is JsonValue {
  let remaining = maximum;
  function text(value: string): boolean {
    let bytes = 0;
    let wire = 2;
    for (let index = 0; index < value.length; index += 1) {
      const code = value.charCodeAt(index);
      if (code >= 0xd800 && code <= 0xdbff) {
        const low = value.charCodeAt(index + 1);
        if (!(low >= 0xdc00 && low <= 0xdfff)) return false;
        bytes += 4;
        wire += 4;
        index += 1;
      } else if (code >= 0xdc00 && code <= 0xdfff) {
        return false;
      } else {
        const width = code < 0x80 ? 1 : code < 0x800 ? 2 : 3;
        bytes += width;
        wire +=
          code === 0x22 || code === 0x5c
            ? 2
            : code < 0x20
              ? [8, 9, 10, 12, 13].includes(code)
                ? 2
                : 6
              : width;
      }
      if (bytes > 1_048_576 || wire > remaining) return false;
    }
    remaining -= wire;
    return remaining >= 0;
  }
  function visit(current: unknown, depth: number): boolean {
    if (depth > 144 || remaining < 0) return false;
    if (typeof current === "string") return text(current);
    if (current === null || typeof current === "boolean") {
      remaining -= current === false ? 5 : 4;
    } else if (typeof current === "number") {
      if (!Number.isFinite(current)) return false;
      remaining -= String(current).length;
    } else if (Array.isArray(current)) {
      if (current.length > 1_000_000) return false;
      remaining -= 2 + Math.max(0, current.length - 1);
      return current.every((child: unknown) => visit(child, depth + 1));
    } else if (isObject(current)) {
      const keys = Object.keys(current);
      if (keys.length > 1_000_000) return false;
      remaining -= 2 + Math.max(0, keys.length - 1) + keys.length;
      return keys.every((key) => text(key) && visit(current[key], depth + 1));
    } else {
      return false;
    }
    return remaining >= 0;
  }
  return visit(value, 0) && remaining >= 0;
}
const isJson: Guard<JsonValue> = (value: unknown): value is JsonValue =>
  boundedJson(value, RESPONSE_MAX_BYTES);
const isResource: Guard<ResourceRef> = (value: unknown): value is ResourceRef => {
  if (
    !isObject(value) ||
    Object.keys(value).length !== 2 ||
    !Object.hasOwn(value, "type") ||
    !Object.hasOwn(value, "id")
  )
    return false;
  switch (value.type) {
    case "pack":
    case "backend":
      return isPackId(value.id);
    case "scenario":
    case "person":
    case "rule":
    case "assignment":
    case "solveRun":
    case "solution":
      return isUuid(value.id);
    default:
      return false;
  }
};
const isValidationIssue = shape<ValidationIssue>({
  code: isText,
  severity: choices("info", "warning", "error"),
  message: isText,
  fieldPath: nullable(isText),
  resource: nullable(isResource),
});
const isFieldError = shape<FieldErrorDto>({ field: isText, code: isText, message: isText });
const isSafeDiagnostic = union<SafeDiagnosticValue>(
  shape<Extract<SafeDiagnosticValue, { readonly type: "text" }>>({
    type: literal("text"),
    value: isText,
  }),
  shape<Extract<SafeDiagnosticValue, { readonly type: "boolean" }>>({
    type: literal("boolean"),
    value: isBoolean,
  }),
  shape<Extract<SafeDiagnosticValue, { readonly type: "integer" }>>({
    type: literal("integer"),
    value: (item: unknown): item is number =>
      typeof item === "number" && Number.isSafeInteger(item),
  }),
);
const isApiError = shape<ApiErrorDto>({
  code: isText,
  message: isText,
  category: choices(
    "validation",
    "conflict",
    "notFound",
    "unsupported",
    "solver",
    "verification",
    "storage",
    "protocol",
    "ai",
    "internal",
  ),
  retryable: isBoolean,
  fieldErrors: arrayOf(isFieldError),
  details: nullable(recordOf(isSafeDiagnostic)),
  diagnosticId: nullable(isUuid),
});
function invalidResponse(): Error & ApiErrorDto {
  const error: ApiErrorDto = {
    code: "protocol.invalid_response",
    category: "protocol",
    message:
      "The application returned an invalid response. Refresh to check the current state before trying again.",
    retryable: false,
    fieldErrors: [],
    details: null,
    diagnosticId: null,
  };
  return Object.assign(new Error(error.message), error);
}
type ResponseRevision<T> =
  | (keyof T & ("revision" | "currentRevision" | "newRevision" | "libraryRevision"))
  | ((result: T) => Revision | null)
  | null;
function parseResponse<T>(
  value: unknown,
  requestId: UuidV7,
  guard: Guard<T>,
  maximum: number,
  revisionKey: ResponseRevision<T> | undefined,
  enforceRequestEcho = true,
): ApiResponseDto<T> {
  const envelope = shape<ApiResponseDto<T>>({
    schemaVersion: literal(API_SCHEMA_VERSION),
    requestId: isUuid,
    currentRevision: nullable(isRevision),
    warnings: arrayOf(isValidationIssue, 100_000),
    result: guard,
  });
  if (!boundedJson(value, maximum) || !envelope(value) || value.requestId !== requestId)
    throw invalidResponse();
  if (revisionKey !== undefined) {
    const resultRevision =
      typeof revisionKey === "function"
        ? revisionKey(value.result)
        : revisionKey === null
          ? null
          : value.result[revisionKey];
    if (resultRevision !== value.currentRevision) throw invalidResponse();
  }
  // These declared top-level fields are invocation echoes, not nested job/domain identities.
  if (
    enforceRequestEcho &&
    isObject(value.result) &&
    ((Object.hasOwn(value.result, "requestId") && value.result.requestId !== requestId) ||
      (Object.hasOwn(value.result, "cancelRequestId") &&
        value.result.cancelRequestId !== requestId))
  )
    throw invalidResponse();
  return value;
}

